inline void CellValue::encode(::synurang::lite::ProtoWriter& w) const {
    switch (value_case) {
        case CellValue::ValueCase::kNone: break;
        case CellValue::ValueCase::kText:
            w.write_string(1, text);
            break;
        case CellValue::ValueCase::kNumber:
            w.write_double(2, number);
            break;
        case CellValue::ValueCase::kFlag:
            w.write_bool(3, flag);
            break;
        case CellValue::ValueCase::kRaw:
            w.write_bytes(4, raw);
            break;
        case CellValue::ValueCase::kTimestamp:
            w.write_int64(5, timestamp);
            break;
    }
}

inline void CellValue::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1:
                text = r.read_string();
                value_case = CellValue::ValueCase::kText;
                break;
            case 2:
                number = r.read_double();
                value_case = CellValue::ValueCase::kNumber;
                break;
            case 3:
                flag = r.read_bool();
                value_case = CellValue::ValueCase::kFlag;
                break;
            case 4:
                raw = r.read_bytes();
                value_case = CellValue::ValueCase::kRaw;
                break;
            case 5:
                timestamp = r.read_int64();
                value_case = CellValue::ValueCase::kTimestamp;
                break;
            default: r.skip(_pb_wire_); break;
        }
    }
}

