inline void EditCommand::encode(::synurang::lite::ProtoWriter& w) const {
    if (grid_id != 0) w.write_int64(1, grid_id);
    switch (command_case) {
        case EditCommand::CommandCase::kNone: break;
        case EditCommand::CommandCase::kStart:
            if (start) {
                ::synurang::lite::ProtoWriter inner;
                start->encode(inner);
                w.write_message_bytes(2, inner.data());
            }
            break;
        case EditCommand::CommandCase::kSession:
            if (session) {
                ::synurang::lite::ProtoWriter inner;
                session->encode(inner);
                w.write_message_bytes(3, inner.data());
            }
            break;
        case EditCommand::CommandCase::kGetState:
            if (get_state) {
                ::synurang::lite::ProtoWriter inner;
                get_state->encode(inner);
                w.write_message_bytes(4, inner.data());
            }
            break;
    }
}

inline void EditCommand::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1: grid_id = r.read_int64(); break;
            case 2: {
                auto body = r.read_length_delimited();
                start = std::make_shared<EditStart>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                start->parse_from(pr);
                command_case = EditCommand::CommandCase::kStart;
                break;
            }
            case 3: {
                auto body = r.read_length_delimited();
                session = std::make_shared<EditorSessionCommand>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                session->parse_from(pr);
                command_case = EditCommand::CommandCase::kSession;
                break;
            }
            case 4: {
                auto body = r.read_length_delimited();
                get_state = std::make_shared<EditGetState>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                get_state->parse_from(pr);
                command_case = EditCommand::CommandCase::kGetState;
                break;
            }
            default: r.skip(_pb_wire_); break;
        }
    }
}

