inline void FrameMetrics::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1: frame_time_ms = r.read_float(); break;
            case 2: fps = r.read_float(); break;
            case 3:
                if (_pb_wire_ == ::synurang::lite::WireType::LengthDelimited && true) {
                    auto body = r.read_length_delimited();
                    ::synurang::lite::ProtoReader pr(body.data(), body.size());
                    while (!pr.eof()) layer_times_us.push_back(pr.read_float());
                } else {
                    layer_times_us.push_back(r.read_float());
                }
                break;
            case 4:
                if (_pb_wire_ == ::synurang::lite::WireType::LengthDelimited && true) {
                    auto body = r.read_length_delimited();
                    ::synurang::lite::ProtoReader pr(body.data(), body.size());
                    while (!pr.eof()) zone_cell_counts.push_back(pr.read_uint32());
                } else {
                    zone_cell_counts.push_back(r.read_uint32());
                }
                break;
            case 5: instance_count = r.read_int32(); break;
            default: r.skip(_pb_wire_); break;
        }
    }
}

