inline void GridEventTarget::encode(::synurang::lite::ProtoWriter& w) const {
    if (static_cast<int32_t>(kind) != 0) w.write_int32(1, static_cast<int32_t>(kind));
    if (static_cast<int32_t>(band) != 0) w.write_int32(2, static_cast<int32_t>(band));
    if (slot_index != 0) w.write_int32(3, slot_index);
    if (slot_kind != 0) w.write_int32(4, slot_kind);
    if (!custom_key.empty()) w.write_string(5, custom_key);
    if (!text.empty()) w.write_string(6, text);
    if (int_value != 0) w.write_int64(7, int_value);
    if (status_flags != 0) w.write_uint32(8, status_flags);
    if (!data.empty()) w.write_bytes(9, data);
    if (sub_mode != 0) w.write_int32(10, sub_mode);
}

