inline void LoadDataOptions::encode(::synurang::lite::ProtoWriter& w) const {
    if (header_policy.has_value()) {
        w.write_int32(10, static_cast<int32_t>(*header_policy));
    }
    for (const auto& item : field_map) {
        ::synurang::lite::ProtoWriter inner;
        item.encode(inner);
        w.write_message_bytes(11, inner.data());
    }
    if (type_policy.has_value()) {
        w.write_int32(12, static_cast<int32_t>(*type_policy));
    }
    if (coercion.has_value()) {
        w.write_int32(13, static_cast<int32_t>(*coercion));
    }
    if (error_mode.has_value()) {
        w.write_int32(14, static_cast<int32_t>(*error_mode));
    }
    if (date_format.has_value()) {
        w.write_string(15, *date_format);
    }
    if (decimal_char.has_value()) {
        w.write_string(16, *decimal_char);
    }
    if (auto_create_columns.has_value()) {
        w.write_bool(17, *auto_create_columns);
    }
    if (atomic.has_value()) {
        w.write_bool(19, *atomic);
    }
    if (skip_rows.has_value()) {
        w.write_int32(20, *skip_rows);
    }
    if (max_rows.has_value()) {
        w.write_int32(21, *max_rows);
    }
    switch (format_case) {
        case LoadDataOptions::FormatCase::kNone: break;
        case LoadDataOptions::FormatCase::kCsv:
            if (csv) {
                ::synurang::lite::ProtoWriter inner;
                csv->encode(inner);
                w.write_message_bytes(1, inner.data());
            }
            break;
        case LoadDataOptions::FormatCase::kJson:
            if (json) {
                ::synurang::lite::ProtoWriter inner;
                json->encode(inner);
                w.write_message_bytes(2, inner.data());
            }
            break;
    }
}

inline void LoadDataOptions::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1: {
                auto body = r.read_length_delimited();
                csv = std::make_shared<CsvOptions>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                csv->parse_from(pr);
                format_case = LoadDataOptions::FormatCase::kCsv;
                break;
            }
            case 2: {
                auto body = r.read_length_delimited();
                json = std::make_shared<JsonOptions>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                json->parse_from(pr);
                format_case = LoadDataOptions::FormatCase::kJson;
                break;
            }
            case 10: header_policy = static_cast<HeaderPolicy>(r.read_int32()); break;
            case 11: {
                auto body = r.read_length_delimited();
                FieldMapping elem;
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                elem.parse_from(pr);
                field_map.push_back(std::move(elem));
                break;
            }
            case 12: type_policy = static_cast<TypePolicy>(r.read_int32()); break;
            case 13: coercion = static_cast<CoercionMode>(r.read_int32()); break;
            case 14: error_mode = static_cast<WriteErrorMode>(r.read_int32()); break;
            case 15: date_format = r.read_string(); break;
            case 16: decimal_char = r.read_string(); break;
            case 17: auto_create_columns = r.read_bool(); break;
            case 19: atomic = r.read_bool(); break;
            case 20: skip_rows = r.read_int32(); break;
            case 21: max_rows = r.read_int32(); break;
            default: r.skip(_pb_wire_); break;
        }
    }
}

