inline void PrintResponse::encode(::synurang::lite::ProtoWriter& w) const {
    for (const auto& item : pages) {
        ::synurang::lite::ProtoWriter inner;
        item.encode(inner);
        w.write_message_bytes(1, inner.data());
    }
}

inline void PrintResponse::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1: {
                auto body = r.read_length_delimited();
                PrintPage elem;
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                elem.parse_from(pr);
                pages.push_back(std::move(elem));
                break;
            }
            default: r.skip(_pb_wire_); break;
        }
    }
}

