inline void RegionStyle::encode(::synurang::lite::ProtoWriter& w) const {
    if (background.has_value()) {
        w.write_uint32(1, *background);
    }
    if (foreground.has_value()) {
        w.write_uint32(2, *foreground);
    }
    if (font) {
        ::synurang::lite::ProtoWriter inner;
        font->encode(inner);
        w.write_message_bytes(3, inner.data());
    }
    if (grid_lines) {
        ::synurang::lite::ProtoWriter inner;
        grid_lines->encode(inner);
        w.write_message_bytes(4, inner.data());
    }
    if (text_effect.has_value()) {
        w.write_int32(5, static_cast<int32_t>(*text_effect));
    }
    if (separator) {
        ::synurang::lite::ProtoWriter inner;
        separator->encode(inner);
        w.write_message_bytes(6, inner.data());
    }
    if (cell_padding) {
        ::synurang::lite::ProtoWriter inner;
        cell_padding->encode(inner);
        w.write_message_bytes(7, inner.data());
    }
}

inline void RegionStyle::parse_from(::synurang::lite::ProtoReader& r) {
    int32_t _pb_field_;
    ::synurang::lite::WireType _pb_wire_;
    while (r.read_tag(_pb_field_, _pb_wire_)) {
        switch (_pb_field_) {
            case 1: background = r.read_uint32(); break;
            case 2: foreground = r.read_uint32(); break;
            case 3: {
                auto body = r.read_length_delimited();
                font = std::make_shared<Font>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                font->parse_from(pr);
                break;
            }
            case 4: {
                auto body = r.read_length_delimited();
                grid_lines = std::make_shared<GridLines>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                grid_lines->parse_from(pr);
                break;
            }
            case 5: text_effect = static_cast<TextEffect>(r.read_int32()); break;
            case 6: {
                auto body = r.read_length_delimited();
                separator = std::make_shared<Separator>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                separator->parse_from(pr);
                break;
            }
            case 7: {
                auto body = r.read_length_delimited();
                cell_padding = std::make_shared<Padding>();
                ::synurang::lite::ProtoReader pr(body.data(), body.size());
                cell_padding->parse_from(pr);
                break;
            }
            default: r.skip(_pb_wire_); break;
        }
    }
}

