template <typename Req, typename Resp>
class SynurangLiteBidiStream {
public:
    explicit SynurangLiteBidiStream(std::unique_ptr<::synurang::lite::Stream> s) : stream_(std::move(s)) {}
    void send(const Req& msg) { stream_->send(msg.serialize()); }
    void close_send() { stream_->close_send(); }
    bool recv(Resp& out) {
        std::vector<uint8_t> bytes;
        if (!stream_->recv(bytes)) return false;
        out = Resp::parse(bytes);
        return true;
    }
    void close() { stream_->close(); }

private:
    std::unique_ptr<::synurang::lite::Stream> stream_;
};


